def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float))

    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pair(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
            return obj[0], obj[1]
        if isinstance(obj, dict):
            if "x" in obj and "y" in obj and is_num(obj.get("x")) and is_num(obj.get("y")):
                return obj.get("x"), obj.get("y")
        return default

    def clamp_move(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def extract_positions(value):
        out = []
        if isinstance(value, dict):
            value = value.get("positions", value.get("cells", value.get("items", value.get("targets", []))))
        if isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, (list, tuple, dict)):
                    p = pair(item, None)
                    if p is not None:
                        out.append(p)
        return out

    env = observation.get("environment_name", "") if isinstance(observation, dict) else ""
    sx, sy = pair(observation.get("self_position", (0, 0)) if isinstance(observation, dict) else (0, 0), (0, 0))
    ox, oy = pair(observation.get("opponent_position", (sx, sy)) if isinstance(observation, dict) else (sx, sy), (sx, sy))
    w = observation.get("grid_width", 0) if isinstance(observation, dict) else 0
    h = observation.get("grid_height", 0) if isinstance(observation, dict) else 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") if isinstance(observation, dict) else "pursuer"
        if role == "pursuer":
            return clamp_move((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return clamp_move((sx, sy), target)

    if env == "territory_control":
        candidates = []
        if isinstance(observation, dict):
            for key in ("frontier_cells", "target_cells", "unclaimed_cells", "opponent_territory", "enemy_cells", "neutral_cells"):
                cells = extract_positions(observation.get(key, []))
                if cells:
                    candidates = cells
                    break
        if candidates:
            best = min(candidates, key=lambda c: (manhattan(c, (sx, sy)), manhattan(c, (ox, oy))))
            return clamp_move((sx, sy), best)
        return [sgn(ox - sx), sgn(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]

    resources = []
    if isinstance(observation, dict):
        for key in ("resources", "resource_positions", "targets", "food", "collectibles", "items"):
            items = extract_positions(observation.get(key, []))
            if items:
                resources = items
                break

    if resources:
        best = min(resources, key=lambda c: (manhattan(c, (sx, sy)), manhattan(c, (ox, oy))))
        return clamp_move((sx, sy), best)

    if isinstance(observation, dict):
        allies = extract_positions(observation.get("allied_positions", [])) or extract_positions(observation.get("teammate_positions", []))
        if allies:
            tx, ty = allies[0]
            return clamp_move((sx, sy), (tx, ty))

    return [sgn(ox - sx), sgn(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]

